}

.mm-footer-link {
  cursor: pointer;
  color: var(--color-mm-primary);
  text-decoration: none;
  border-bottom: 1px solid transparent;
  padding-bottom: 1px;
  transition: border-color 200ms, color 200ms, opacity 200ms;
}

.mm-footer-link:hover {
  border-color: var(--color-mm-cta);
  color: var(--color-mm-word);
}

/* —— Shared inner pages —— */
.mm-page {
  padding-block: 2.75rem 3.75rem;
}

.mm-page-title {
  font-size: clamp(2.15rem, 5vw, 3.35rem);
  line-height: 1.05;
  letter-spacing: -0.035em;
  color: var(--color-mm-primary);
}

.mm-page-lead {
  margin-top: 0.75rem;
  max-width: 36rem;
  font-size: 0.92rem;
  line-height: 1.6;
  color: var(--color-mm-secondary);
}

.mm-page-banner {
  margin-bottom: 2rem;
  padding-bottom: 1.75rem;
  border-bottom: 1px solid var(--color-mm-line);
  background:
    linear-gradient(180deg, rgba(184, 149, 108, 0.07), transparent 100%);
  margin-inline: -0.25rem;
  padding-inline: 0.25rem;
}

.mm-back-link {
  display: inline-flex;
  align-items: center;
  cursor: pointer;
  font-size: 0.82rem;
  font-weight: 500;
  letter-spacing: 0.03em;
  color: var(--color-mm-secondary);
  text-decoration: none;
  border-bottom: 1px solid transparent;
  padding-bottom: 1px;
  transition: color 200ms, border-color 200ms;
}

.mm-back-link:hover {
  color: var(--color-mm-primary);
  border-color: var(--color-mm-cta);
}

.mm-panel {
  border: 1px solid var(--color-mm-line);
  background:
    linear-gradient(165deg, rgba(255, 251, 246, 0.98) 0%, rgba(245, 239, 230, 0.72) 100%);
  box-shadow: 0 1px 0 rgba(255, 255, 255, 0.65) inset, 0 12px 32px rgba(28, 22, 18, 0.05);
  padding: 1.5rem;
}

@media (min-width: 768px) {
  .mm-panel {
    padding: 2rem;
  }
}

.mm-panel-inset {
  border: 1px solid var(--color-mm-line);
  background: rgba(237, 224, 212, 0.45);
  padding: 0.85rem 1rem;
}

.mm-list-panel {
  border: 1px solid var(--color-mm-line);
  background: var(--color-mm-surface);
  overflow: hidden;
  box-shadow: 0 8px 24px rgba(28, 22, 18, 0.05);
}

.mm-list-panel > * + * {
  border-top: 1px solid var(--color-mm-line);
}

.mm-eyebrow {
  font-size: 0.68rem;
  font-weight: 600;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--color-mm-word);
}

.mm-auth-shell {
  width: min(28rem, 100%);
  margin-inline: auto;
}

.mm-contact-shell {
  width: min(32rem, 100%);
  margin-inline: auto;
}

.mm-legal-article {
  width: min(42rem, 100%);
  margin-inline: auto;
}

.mm-legal-article header {
  margin-bottom: 2rem;
  padding-bottom: 1.5rem;
  border-bottom: 1px solid var(--color-mm-line);
}

.mm-legal-article h2 {
  font-size: 1.05rem;
  font-weight: 700;
  color: var(--color-mm-primary);
  letter-spacing: -0.01em;
}

.mm-thumb {
  aspect-ratio: 1;
  border: 1px solid var(--color-mm-line);
  object-fit: cover;
  transition: border-color 200ms;
}

.mm-thumb:hover {
  border-color: var(--color-mm-cta);
}

.mm-dialog {
  width: min(28rem, 100%);
  border: 1px solid var(--color-mm-line);
  background:
    linear-gradient(165deg, #fffbf6 0%, #f5efe6 100%);
  box-shadow: 0 24px 60px rgba(28, 22, 18, 0.28);
  padding: 1.5rem;
}

.mm-scroller-btn {
  position: absolute;
  top: 50%;
  z-index: 10;
  display: none;
  height: 2.5rem;
  width: 2.5rem;
  cursor: pointer;
  align-items: center;
  justify-content: center;
  border: 1px solid var(--color-mm-line);
  background: rgba(255, 251, 246, 0.92);
  backdrop-filter: blur(8px);
  color: var(--color-mm-primary);
  font-size: 1.1rem;
  transform: translateY(-50%);
  transition: background-color 200ms, border-color 200ms, color 200ms;
}

.mm-scroller-btn:hover {
  background: var(--color-mm-cta);
  border-color: var(--color-mm-cta);
}

@media (min-width: 768px) {
  .mm-scroller-btn {
    display: flex;
  }
}

.mm-scroller-btn--prev {
  inset-inline-start: 0;
}

.mm-scroller-btn--next {
  inset-inline-end: 0;
}

